#!/usr/bin/env node
// Writes the sound-design skill's references/kits.md from the shipped kits + pack (run by scripts/sync-plugins.mjs).
//   node scripts/kit-docs.mjs <out.md>
import { writeFileSync } from 'node:fs';
import { KIT_NAMES, ROLES, EVENT_ROLES, loadKit, resolveKit, pack } from './lib/kits.mjs';

const out = process.argv[2];
if (!out) { console.error('usage: kit-docs.mjs <out.md>'); process.exit(2); }
const P = pack();
const L = [];
L.push('# Sound kits: every role, sound and placement rule', '',
  '<!-- generated by remotion-engine/assets/engine/scripts/kit-docs.mjs from sfx-pack/ — do not edit by hand -->', '',
  `The sounds come from [earshot](${P.source?.url}) (MIT; bank \`${P.source?.bank}\`), pre-rendered into the engine's`,
  '`sfx-pack/` with their measured sync points. Pick a kit in DESIGN.md (`audio.sfx.kit`), audition it with',
  '`node .motion-graphics/mg.mjs sfx --kit <name>`, and override single roles with `audio.sfx.roles`.', '',
  '**Columns.** *align*: the point of the sound placed on the event (onset = its attack, peak = its loudest 5 ms).',
  '*offset*: where that point lands against the frame (negative = leads the picture). *over bed*: the effect\'s loudest',
  '50 ms over the music\'s level in the second before (used when the video has music). *level*: the role\'s level when',
  'there is no music (dB, loudest role at 0). *gap*: minimum spacing in a run (closer events are skipped). Placement',
  'and level numbers are medians earshot measured on professional launch films; every kit uses them unless its own',
  'role says otherwise.', '');
L.push('## Events → roles (defaults; override with `audio.sfx.events`)', '', '| event | fires when | role |', '|---|---|---|');
const WHEN = {
  scene_in: 'a scene starts', label_in: 'a tag / label glitches in', word_in: 'each word of a words reveal', words_done: 'a words reveal has fully resolved',
  decode_start: 'a hero starts scrambling', decode_land: 'a HERO decode locks', decode_land_minor: 'a non-hero decode locks', type_char: 'a typed character',
  type_space: 'a typed space', type_done: 'typing finished', count_tick: 'a counter step', count_land: 'the counter\'s final number', strike: 'a strike-through draws',
  fade_in: 'an element fades / pops in', logo_in: 'the end-card logo', exit: 'a scene starts dimming', transition: 'a glitch / flash cut (the cut frame)',
};
for (const [e, r] of Object.entries(EVENT_ROLES)) L.push(`| \`${e}\` | ${WHEN[e] || ''} | ${r ? `\`${r}\`` : '— (silent)'} |`);
L.push('', 'Scene extras in CHOREOGRAPHY.md: `sfx: [{ role: riser, at_s: 3.0 }, { role: bell, at_s: 1.2, note: E5 }, { id: impact_punch, at_s: 2 }]`.',
  '`at_s` is the moment the sound should LAND (its aligned point), not where the file starts: a riser at the hero\'s time peaks into it.', '');
for (const k of KIT_NAMES) {
  const kit = loadKit(k), eff = resolveKit({ kit: k });
  L.push(`## \`${k}\``, '', kit.note, '');
  if (kit.mix?.stop_down) L.push(`Music stop-down before: ${kit.mix.stop_down.before.join(', ')} (depth ${kit.mix.stop_down.depth_db.join('–')} dB, ${kit.mix.stop_down.length_s.join('–')} s, back on the hit).`, '');
  L.push('| role | sound | takes | align | offset ms | over bed dB | level dB | gap ms | notes |', '|---|---|--:|---|--:|--:|--:|--:|---|');
  for (const r of ROLES) {
    const x = eff.roles[r];
    if (!x) { L.push(`| ${r} | — off — | | | | | | | ${kit.off?.[r] || ''} |`); continue; }
    const takes = x.takes?.length || P.sounds[x.sound]?.takes.length || 1;
    const tones = x.pitches ? `tuned into the music's key: ${x.pitches.join(' ')}. ` : '';
    L.push(`| ${r} | \`${x.sound}\` | ${takes} | ${x.align} | ${x.offset_ms ?? 0} | ${x.bed_db ?? '—'} | ${x.level_db ?? '—'} | ${x.min_gap_ms ?? ''} | ${tones}${(x.note || '').replace(/\|/g, '/').slice(0, 220)} |`);
  }
  L.push('');
}
L.push('## All pack sounds (usable as `audio.sfx.roles.<role>.sound`)', '', '| sound | category | takes | licence |', '|---|---|--:|---|');
for (const [id, s] of Object.entries(P.sounds)) L.push(`| \`${id}\` | ${s.category} | ${s.takes.length} | ${s.license} |`);
L.push('', 'Credits for the CC0 recordings behind the `fit/…` sounds: the engine\'s `sfx-pack/CREDITS.md`.', '');
writeFileSync(out, L.join('\n'));
console.log(`✔ ${out}`);
